const fs = require('fs')
const path = require('path')

class Cache {
  constructor(dir) {
    this.dir = dir
    fs.mkdirSync(dir, { recursive: true })
  }

  _key(id) {
    return path.join(this.dir, id.replace(/[^a-z0-9_\-]/gi, '_') + '.json')
  }

  read(id) {
    try { return JSON.parse(fs.readFileSync(this._key(id), 'utf8')) } catch { return null }
  }

  write(id, data) {
    fs.writeFileSync(this._key(id), JSON.stringify(data, null, 2))
  }

  has(id) { return fs.existsSync(this._key(id)) }

  list() {
    return fs.readdirSync(this.dir)
      .filter(f => f.endsWith('.json'))
      .map(f => f.replace(/\.json$/, ''))
  }
}

module.exports = new Cache(process.env.CACHE_DIR || './cache')
```

